function useIndependentSquads() {
  const [data, setData] = Q.useState(null), [note, setNote] = Q.useState("");
  Q.useEffect(() => {
    let disposed = false, busy = false;
    async function refresh() {
      if (busy || document.hidden) return; busy = true;
      try { const api = (await import("/mountain-ui.js")).api, next = await api("/api/squads"); if (!disposed) setData(next); }
      catch { /* Existing sign-in UI handles expired and guest sessions. */ }
      finally { busy = false; }
    }
    refresh(); const timer = setInterval(refresh, 3000);
    window.addEventListener("independent-squads-updated", refresh);
    return () => { disposed = true; clearInterval(timer); window.removeEventListener("independent-squads-updated", refresh); };
  }, []);
  async function action(path, body) {
    setNote("");
    try { const api = (await import("/mountain-ui.js")).api; setData(await api(path, body)); window.dispatchEvent(new Event("independent-squads-updated")); }
    catch (e) { setNote(e.message); }
  }
  return { data, note, action };
}
